static void multiply_scalar(const double* input, double* output,
                            int n, bool transpose) {
#ifdef _OPENMP
#pragma omp parallel for schedule(static) if(n >= 512) num_threads(std::min(16, omp_get_max_threads()))
#endif
    for (int i = 0; i < n; ++i) {
