        for (int j = 0; j < n; ++j) {
            const double s = static_cast<double>(i) + j;
            const double denominator =
                s * (s + 1.0) * 0.5 + (transpose ? j : i) + 1.0;
            sum += input[j] / denominator;
        }
        output[i] = sum;
    }
}

