    const __m128d halves = _mm_add_pd(
        _mm256_castpd256_pd128(value),
        _mm256_extractf128_pd(value, 1));
    return _mm_cvtsd_f64(
        _mm_add_sd(halves, _mm_unpackhi_pd(halves, halves)));
