int main(int argc, char** argv) {
    if (argc < 2)
        return 1;

    char* end = nullptr;
    const long parsed = std::strtol(argv[1], &end, 10);
    if (end == argv[1] || *end != '\0' ||
        parsed <= 0 || parsed > 2147483647L)
        return 1;

    const int n = static_cast<int>(parsed);
    std::vector<double> u(n, 1.0), v(n), temporary(n);

    using Multiply = void (*)(const double*, double*, int, bool);
    Multiply multiply = multiply_scalar;

#if HAVE_AVX2_TARGET
    __builtin_cpu_init();
    if (__builtin_cpu_supports("avx2"))
        multiply = multiply_avx2;
#endif

    for (int iteration = 0; iteration < 10; ++iteration) {
        multiply(u.data(), temporary.data(), n, false);
        multiply(temporary.data(), v.data(), n, true);
        multiply(v.data(), temporary.data(), n, false);
        multiply(temporary.data(), u.data(), n, true);
    }

    double uv = 0.0;
    double vv = 0.0;
    for (int i = 0; i < n; ++i) {
        uv += u[i] * v[i];
        vv += v[i] * v[i];
    }

    std::printf("%.9f\n", std::sqrt(uv / vv));
    return 0;
}

